"""Guard Activity page shell."""

GUARD_ACTIVITY_PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Guard Activity</title>
<style>
:root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,sans-serif;color:#17202a;background:#f3f6f8;line-height:1.45}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1080px;margin:auto;padding:28px 18px 56px}h1,h2,h3,p{margin:0}h1{font-size:1.8rem;letter-spacing:-.03em}.muted{color:#6d7b86;font-size:.88rem}.top{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:22px}.live{display:inline-flex;align-items:center;gap:6px;background:#e4f6ec;color:#176b43;border-radius:999px;padding:5px 10px;font-size:.78rem;font-weight:700}.live:before{content:"";width:7px;height:7px;background:#2aa76d;border-radius:50%}.subtitle{margin-top:3px;color:#6d7b86}.filters,.summary,.panel{background:#fff;border:1px solid #dbe3e8;border-radius:14px;box-shadow:0 2px 8px #1b34400b}.filters{display:flex;gap:8px;flex-wrap:wrap;padding:12px;margin-bottom:14px}.filters input,.filters select,.filters button{font:inherit;padding:8px 10px;border:1px solid #cbd5dc;border-radius:8px;background:#fff}.filters button{cursor:pointer}.filters .primary{background:#1768cf;color:#fff;border-color:#1768cf}.filters .refresh{margin-left:auto}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;overflow:hidden;margin-bottom:22px}.metric{padding:15px 16px;background:#fff}.metric strong{display:block;font-size:1.65rem;letter-spacing:-.03em}.metric span{font-size:.78rem;color:#6d7b86}.results{display:grid;gap:9px}.row{width:100%;text-align:left;border:1px solid #dbe3e8;background:#fff;border-radius:12px;padding:14px 16px;cursor:pointer;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;box-shadow:0 1px 4px #1b344008}.row:hover{border-color:#9bbde1}.row-title{display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-weight:750}.row-meta{margin-top:4px;font-size:.82rem;color:#6d7b86}.row-summary{margin-top:7px;font-size:.9rem;color:#34434d;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.row-side{text-align:right;display:grid;justify-items:end;gap:6px}.badge{display:inline-flex;align-items:center;border-radius:999px;padding:4px 9px;font-size:.72rem;font-weight:800;text-transform:uppercase;letter-spacing:.04em}.yes{background:#ffe4e7;color:#a1283d}.no{background:#e5f4eb;color:#176b43}.unknown{background:#edf0f2;color:#576670}.delivery{font-size:.76rem;color:#53636e}.delivery.sent{color:#176b43}.delivery.failed,.delivery.unconfirmed{color:#a1283d}.delivery.scheduled{color:#996400}.empty{padding:38px;text-align:center}.panel{padding:20px;margin-top:18px}.panel-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.close{border:0;background:transparent;color:#6d7b86;font-size:1.2rem;cursor:pointer}.detail-meta{margin-top:6px;color:#6d7b86;font-size:.88rem}.reason{margin-top:18px;font-size:1.05rem}.section{margin-top:20px;border-top:1px solid #e3e9ed;padding-top:15px}.section h3{font-size:.78rem;text-transform:uppercase;letter-spacing:.07em;color:#6d7b86;margin-bottom:9px}.evidence,.context{display:grid;gap:7px}.message{background:#f6f8fa;border-radius:8px;padding:9px 11px;font-size:.86rem}.message.cited{border-left:3px solid #1768cf}.message-head{display:flex;justify-content:space-between;gap:10px;color:#6d7b86;font-size:.73rem;margin-bottom:3px}.unavailable{color:#a1283d;font-style:italic}.context-toggle{font:inherit;border:1px solid #cbd5dc;background:#fff;border-radius:8px;padding:8px 10px;cursor:pointer}.trust{font-size:.82rem;color:#53636e;margin-bottom:9px}.error{color:#a1283d;background:#fff0f1;border-radius:8px;padding:9px}.more{display:block;margin:14px auto 0;font:inherit;padding:8px 13px;border:1px solid #cbd5dc;background:#fff;border-radius:8px;cursor:pointer}@media(max-width:650px){.summary{grid-template-columns:1fr 1fr}.top{display:block}.live{margin-top:10px}.row{grid-template-columns:1fr}.row-side{text-align:left;display:flex;justify-content:space-between;align-items:center}.filters .refresh{margin-left:0}}
</style></head><body><main class="wrap">
<header class="top"><div><h1>Echo Guard — Activity</h1><div class="subtitle">Parent attention monitoring</div></div><span class="live">Live</span></header>
<form class="filters" onsubmit="load(event)"><select id="child"><option value="">All children</option></select><input id="chat" placeholder="Chat ID"><select id="decision"><option value="">YES / NO / UNKNOWN</option><option value="yes">YES</option><option value="no">NO</option><option value="unknown">UNKNOWN</option></select><label class="muted">From <input id="from" type="date"></label><label class="muted">To <input id="to" type="date"></label><button class="primary">Apply</button><button type="button" class="refresh" onclick="load()">Refresh</button></form>
<section id="summary" class="summary"></section><section id="results" class="results"></section><button id="more" class="more" hidden onclick="loadMore()">Load more</button>
<section id="detail" class="panel" hidden></section>
</main><script>
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const fmt=v=>v?new Date(v).toLocaleString(): '—';
let cursor=null,loading=false;
function decisionClass(v){return v==='yes'?'yes':v==='no'?'no':'unknown'}
function message(m){if(m.unavailable)return `<div class="message unavailable"><div class="message-head"><span>${esc(m.id)}</span><span>Unavailable</span></div>Message content is no longer available.</div>`;return `<div class="message ${m.cited?'cited':''}"><div class="message-head"><span>${esc(m.sender)}${m.cited?' · Evidence':''}</span><span>${fmt(m.timestamp)}</span></div><div>${esc(m.text)}</div></div>`}
function params(){const p=new URLSearchParams();for(const [id,key] of [['child','child_id'],['chat','chat_id'],['decision','decision'],['from','date_from'],['to','date_to']]){const v=document.getElementById(id).value;if(v)p.set(key,v)}if(cursor)p.set('cursor',cursor);return p}
async function load(e){if(e)e.preventDefault();if(loading)return;loading=true;if(!cursor)document.getElementById('results').innerHTML='<div class="empty muted">Loading analyses…</div>';try{const r=await fetch('/api/debug/guard/operations?'+params());if(!r.ok)throw new Error('Unable to load Guard Activity');const data=await r.json();if(!cursor){renderSummary(data.summary);renderChildren(data.children);document.getElementById('results').innerHTML=''}renderRows(data.analyses);cursor=data.next_cursor;document.getElementById('more').hidden=!cursor}catch(err){document.getElementById('results').innerHTML=`<div class="error">${esc(err.message)}</div>`}finally{loading=false}}
function loadMore(){load()}
function renderSummary(s){document.getElementById('summary').innerHTML=[['analyzed','Analyzed'],['yes','YES'],['no','NO'],['notifications','Confirmed notifications']].map(([k,l])=>`<div class="metric"><strong>${s[k]??0}</strong><span>${l}</span></div>`).join('')}
function renderChildren(children){const el=document.getElementById('child');const current=el.value;el.innerHTML='<option value="">All children</option>'+children.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');el.value=current}
function renderRows(rows){if(!rows.length&&!cursor){document.getElementById('results').innerHTML='<div class="empty muted">No analyses in the selected period.</div>';return}for(const a of rows){const b=decisionClass(a.decision);const d=a.delivery||{};const button=document.createElement('button');button.className='row';button.innerHTML=`<div><div class="row-title"><span>${esc(a.chat_name)}</span><span class="badge ${b}">${esc(a.decision)}</span></div><div class="row-meta">${esc(a.child_name)} · ${fmt(a.created_at)} · ${a.message_count??'—'} messages</div><div class="row-summary">${esc(a.summary)}</div></div><div class="row-side"><span class="delivery ${esc(d.status)}">${esc(d.label)}</span></div>`;button.onclick=()=>openAnalysis(a.id);document.getElementById('results').appendChild(button)}}
async function openAnalysis(id){const detail=document.getElementById('detail');detail.hidden=false;detail.innerHTML='<div class="muted">Loading analysis…</div>';try{const r=await fetch('/api/debug/guard/operations/'+encodeURIComponent(id));if(!r.ok)throw new Error('Analysis not found');const a=await r.json();detail.innerHTML=`<div class="panel-head"><div><h2><span class="badge ${decisionClass(a.decision)}">${esc(a.decision)}</span></h2><div class="detail-meta">${esc(a.child_name)} · ${esc(a.chat_name)} · ${fmt(a.created_at)} · ${a.context_message_count||'—'} messages</div></div><button class="close" onclick="closeDetail()">×</button></div><p class="reason">${esc(a.reason)}</p><div class="section"><h3>Evidence from the conversation</h3><div class="evidence">${(a.evidence_messages||[]).map(message).join('')||'<span class="muted">No cited evidence.</span>'}</div></div><div class="section"><h3>Delivery</h3><div class="delivery ${esc(a.delivery?.status)}">${esc(a.delivery?.label||'Unknown (historical)')} · ${esc(a.delivery?.reason||'')}</div></div><div class="section"><h3>Conversation snapshot</h3><button class="context-toggle" onclick="loadContext('${esc(id)}')">Expand conversation snapshot</button><div id="context" class="context" hidden></div></div>`;detail.scrollIntoView({behavior:'smooth',block:'start'})}catch(err){detail.innerHTML=`<div class="error">${esc(err.message)}</div>`}}
async function loadContext(id){const box=document.getElementById('context');box.hidden=false;box.innerHTML='<div class="muted">Loading conversation…</div>';try{const r=await fetch('/api/debug/guard/operations/'+encodeURIComponent(id)+'/context');if(!r.ok)throw new Error('Unable to load conversation');const c=await r.json();box.innerHTML=`<div class="trust">${esc(c.trust)}</div>${(c.messages||[]).map(message).join('')||'<span class="muted">No messages available.</span>'}`}catch(err){box.innerHTML=`<div class="error">${esc(err.message)}</div>`}}
function closeDetail(){const d=document.getElementById('detail');d.hidden=true;d.innerHTML=''}
load();
</script></body></html>'''

__all__ = ["GUARD_ACTIVITY_PAGE"]
